24	/// Same shape as `capture_flow_e2e_test.dart`'s/`entry_detail_flow_e2e_
25	/// test.dart`'s own fake adapter, extended with [queueSseResponse] for
26	/// `ApiClient.postStream`'s `ResponseType.stream` requests — only the
27	/// transport boundary is faked.
28	///
29	/// A queued SSE response is delivered as the exact [chunks] given, each
30	/// its own separate stream emission (never pre-joined into one string) —
31	/// this is what proves `ChatRemoteDataSource.sendMessage`'s own
32	/// `\n\n`-boundary buffering really works across genuine network chunk
33	/// boundaries, not just against a single already-complete event.
34	class _FakeHttpClientAdapter implements HttpClientAdapter {
35	  final List<RequestOptions> requests = [];
36	  final List<ResponseBody Function()> _queue = [];
37	
38	  // spec-6-5 — `_fireInsightTrigger`'s own `chat-insight-create` POST
39	  // fires unawaited, concurrently with whichever `chat-messages-send`
40	  // POST is already in flight for that same `sendMessage()` call, so the
41	  // two requests' real arrival order at this adapter isn't deterministic
42	  // the way every other (sequential) call in this file is. Routed by a
43	  // path substring instead of the shared FIFO `_queue` above, so each
44	  // queue's own order stays independent of the other's.
45	  final Map<String, List<ResponseBody Function()>> _routedQueue = {};
46	
47	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
48	    _queue.add(
49	      () => ResponseBody.fromString(
50	        jsonEncode(body),
51	        statusCode,
52	        headers: {
53	          Headers.contentTypeHeader: [Headers.jsonContentType],
54	        },
55	      ),
56	    );
57	  }
58	
59	  void queueErrorResponse(String code, String message, {int statusCode = 503}) {
60	    queueJsonResponse(statusCode, {
61	      'code': code,
62	      'message': message,
63	      'retryable': true,
64	    });
65	  }
66	
67	  void queueResponseForPath(
68	    String pathSubstring,
69	    int statusCode,
70	    Map<String, dynamic> body,
71	  ) {
72	    (_routedQueue[pathSubstring] ??= []).add(
73	      () => ResponseBody.fromString(
74	        jsonEncode(body),
75	        statusCode,
76	        headers: {
77	          Headers.contentTypeHeader: [Headers.jsonContentType],
78	        },
79	      ),
80	    );
81	  }
82	
83	  void queueErrorResponseForPath(
84	    String pathSubstring,
85	    String code,
86	    String message, {
87	    int statusCode = 503,
88	  }) {
89	    queueResponseForPath(pathSubstring, statusCode, {
90	      'code': code,
91	      'message': message,
92	      'retryable': true,
93	    });
94	  }
95	
96	  void queueSseResponse(List<String> chunks, {int statusCode = 200}) {
97	    _queue.add(
98	      () => ResponseBody(
99	        Stream.fromIterable(
100	          chunks.map((chunk) => Uint8List.fromList(utf8.encode(chunk))),
101	        ),
102	        statusCode,
103	        headers: {
104	          Headers.contentTypeHeader: ['text/event-stream'],
105	        },
106	      ),
107	    );
108	  }
109	
110	  @override
111	  Future<ResponseBody> fetch(
112	    RequestOptions options,
113	    Stream<Uint8List>? requestStream,
114	    Future<void>? cancelFuture,
115	  ) async {
116	    requests.add(options);
117	    for (final entry in _routedQueue.entries) {
118	      if (options.path.contains(entry.key) && entry.value.isNotEmpty) {
119	        return entry.value.removeAt(0)();
120	      }
121	    }
122	    if (_queue.isEmpty) {
123	      throw StateError(
124	        'No queued response for ${options.method} ${options.path}',
125	      );
126	    }
127	    return _queue.removeAt(0)();
128	  }
129	
130	  @override
131	  void close({bool force = false}) {}
132	}
