184	/// Queues a trivial one-token-then-done SSE response for a plain
185	/// `sendMessage()` call that isn't itself the focus of the assertion —
186	/// spec-6-5's own tests need several of these to drive the message-count
187	/// window toward its threshold.
188	void _queuePlainReply(_FakeHttpClientAdapter adapter, String reply) {
189	  adapter.queueSseResponse([
190	    'event: token\ndata: {"delta":"$reply"}\n\nevent: done\ndata: {}\n\n',
191	  ]);
192	}
