194	/// End-to-end coverage for spec-6-1's chat flow, driven through the real
195	/// production object graph `sl` resolves for Home/Chat (the exact
196	/// `ChatCubit` instance `app_router.dart` gives `ChatScreen`), wired to
197	/// the real `ChatRepositoryImpl` -> `ChatRemoteDataSource` -> `ApiClient`
198	/// -> `Dio` (both real interceptors attached) -> the real `chat_sessions`/
199	/// `chat_messages` Hive boxes. Only the transport boundary and the native
200	/// plugins (secure storage, path_provider) are faked — no device/
201	/// simulator/CI exists yet (AGENTS.md).
202	///
203	/// Complements rather than duplicates this story's existing mocked tests
204	/// (`chat_cubit_test.dart` against a fake `ChatRepository`,
205	/// `chat_repository_impl_test.dart`/`chat_remote_data_source_test.dart`
206	/// against a mocked `ApiClient`): none of them drives a real SSE byte
207	/// stream through the real `ApiClient.postStream` -> `ChatRemoteDataSource`
208	/// `\n\n`-buffering -> `ChatCubit` token-append pipeline in one send, the
209	/// way the app actually does on every message.
210	///
211	/// Driven directly against `ChatCubit`'s own public API (`init`/
212	/// `sendMessage`), not through `tester.tap`/`pumpAndSettle` — same
213	/// rationale `capture_flow_e2e_test.dart` documents: these awaits span
214	/// genuine async I/O (a real Dio round trip over a faked transport), and
215	/// `pumpAndSettle` isn't guaranteed to wait for that.
216	void main() {
217	  TestWidgetsFlutterBinding.ensureInitialized();
218	
219	  const secureStorageChannel = MethodChannel(
220	    'plugins.it_nomads.com/flutter_secure_storage',
221	  );
222	  final fakeNativeStorage = <String, String>{};
223	
224	  // spec-6-3 — `sl<ChatCubit>()` below resolves the *real* `ChatCubit`,
225	  // whose constructor subscribes to the real `connectivity_plus`-backed
226	  // `ConnectivityWatcher` immediately; faked the same way
227	  // `bootstrap_integration_test.dart` fakes it, since no device/simulator
228	  // exists yet (AGENTS.md) to answer these channels for real.
229	  const connectivityMethodChannel = MethodChannel(
230	    'dev.fluttercommunity.plus/connectivity',
231	  );
232	  const connectivityEventChannel = EventChannel(
233	    'dev.fluttercommunity.plus/connectivity_status',
234	  );
235	
236	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
237	    final args = call.arguments as Map<dynamic, dynamic>;
238	    switch (call.method) {
239	      case 'write':
240	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
241	        return null;
242	      case 'read':
243	        return fakeNativeStorage[args['key'] as String];
244	      case 'delete':
245	        fakeNativeStorage.remove(args['key'] as String);
246	        return null;
247	      case 'containsKey':
248	        return fakeNativeStorage.containsKey(args['key'] as String);
249	      default:
250	        return null;
251	    }
252	  }
253	
254	  late FakePathProviderPlatform fakePathProvider;
255	  late _FakeHttpClientAdapter adapter;
256	
257	  // spec-6-3 — the real `connectivity_plus` plugin reaches this channel's
258	  // own event stream via `EventChannel.receiveBroadcastStream()`, not a
259	  // plain method call, so it must be mocked with `setMockStreamHandler`
260	  // rather than `setMockMethodCallHandler` to let a test push a live
261	  // reading. Captured on `onListen` (fired as soon as `sl<ChatCubit>()`'s
262	  // own constructor subscribes) so a test can call
263	  // `connectivityEventSink!.success([...])` to simulate a connectivity
264	  // change arriving from the OS.
265	  MockStreamHandlerEventSink? connectivityEventSink;
266	
267	  /// Pushes a live `connectivity_plus` reading and flushes the microtask
268	  /// hops between the fake event channel and `ChatCubit`'s own listener
269	  /// (the channel's `receiveBroadcastStream` -> `connectivity_plus`'s
270	  /// `distinct()` wrapper -> `ConnectivityPlusWatcher`'s own controller ->
271	  /// `ChatCubit._handleConnectivityChange`) — same `Future.delayed(Duration.
272	  /// zero)`-per-hop convention `connectivity_plus_watcher_test.dart` uses.
273	  Future<void> emitConnectivity(List<String> results) async {
274	    connectivityEventSink!.success(results);
275	    for (var i = 0; i < 5; i++) {
276	      await Future<void>.delayed(Duration.zero);
277	    }
278	  }
