280	  setUp(() async {
281	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
282	        .setMockMethodCallHandler(
283	          secureStorageChannel,
284	          handleSecureStorageCall,
285	        );
286	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
287	        .setMockMethodCallHandler(
288	          connectivityMethodChannel,
289	          (call) async => call.method == 'check' ? <String>['wifi'] : null,
290	        );
291	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
292	        .setMockStreamHandler(
293	          connectivityEventChannel,
294	          MockStreamHandler.inline(
295	            onListen: (_, events) => connectivityEventSink = events,
296	            onCancel: (_) => connectivityEventSink = null,
297	          ),
298	        );
299	    fakePathProvider = FakePathProviderPlatform();
300	    PathProviderPlatform.instance = fakePathProvider;
301	
302	    await resetCoreDependencies();
303	    await setupCoreDependencies();
304	
305	    adapter = _FakeHttpClientAdapter();
306	    sl<Dio>().httpClientAdapter = adapter;
307	
308	    // `chat-messages-send` et al. are bearer-required operations — seed a
309	    // user access token through the real `AccessTokenProvider` so the
310	    // real header interceptor has one to send.
311	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
312	  });
