import '../../core/di/injection_container.dart';
import '../../core/network/access_token_provider.dart';
import '../../core/session/session_expiry_notifier.dart';
import 'data/datasources/auth_remote_data_source.dart';
import 'data/repositories/auth_repository_impl.dart';
import 'data/repositories/session_repository_impl.dart';
import 'domain/repositories/auth_repository.dart';
import 'domain/repositories/session_repository.dart';
import 'presentation/cubit/auth_cubit.dart';

/// Registers the `auth` feature into the project's single `get_it` instance
/// (`sl`). Called from `setupCoreDependencies()` once core infrastructure is
/// up, since this feature only needs `ApiClient`/`AccessTokenProvider`,
/// already registered there.
void registerAuthFeature() {
  sl.registerLazySingleton<AuthRemoteDataSource>(
    () => AuthRemoteDataSource(sl()),
  );

  sl.registerLazySingleton<AuthRepository>(
    () => AuthRepositoryImpl(
      remoteDataSource: sl(),
      accessTokenProvider: sl<AccessTokenProvider>(),
    ),
  );

  // The epic's ONE new DI-singleton access point for session validity (AD) —
  // registered as a singleton so every consumer (`main.dart` here; Story
  // 1.5's overlay and Story 1.6's `go_router` redirect later) shares the
  // same `statusStream`, not a fresh instance each. `dispose:` wires
  // `SessionRepository.dispose()` into `get_it`'s own reset lifecycle, so
  // `resetCoreDependencies()` (`sl.reset()`) closes its `StreamController`
  // instead of leaking one on every test teardown.
  sl.registerLazySingleton<SessionRepository>(
    () => SessionRepositoryImpl(
      remoteDataSource: sl(),
      accessTokenProvider: sl<AccessTokenProvider>(),
      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
    ),
    dispose: (repository) => repository.dispose(),
  );

  // Story 1.6 — `AuthCubit` additionally depends on `SessionRepository`
  // (registered above) so its `submit()` success branch can call
  // `markAuthenticated()`.
  sl.registerLazySingleton<AuthCubit>(
    () => AuthCubit(sl(), sl<SessionRepository>()),
  );
}

import 'package:fpdart/fpdart.dart';

import '../../../../core/resource.dart';

/// Tela 0.1a's two modes — toggled by a text link, never a separate screen
/// (epics.md Story 1.3 AC).
enum AuthMode { login, signUp }

/// Drives [AuthScreen]: mode, the two field values, their errors, and the
/// in-flight submit status.
///
/// [emailError] and [passwordError] are each single-field, pre-network local
/// validation errors — set independently, one per field, never together
/// (`AuthCubit.submit` checks email first and returns before ever touching
/// password validation). [formError] is reserved for an actual backend-call
/// failure (`AUTH_INVALID`/network/any other `Failure`) — it never overlaps
/// with either local error, since `submit` only reaches the network call
/// once both local checks already passed.
class AuthState {
  const AuthState({
    this.mode = AuthMode.login,
    this.email = '',
    this.password = '',
    this.emailError,
    this.passwordError,
    this.formError,
    this.status = const ResourceIdle<Unit>(),
  });

  final AuthMode mode;
  final String email;
  final String password;

  /// Inline "E-mail inválido" from local validation. Shown under the e-mail
  /// field only.
  final String? emailError;

  /// Inline "Senha obrigatória" from local validation. Shown under the
  /// senha field only — unlike [formError], this never borders the e-mail
  /// field too (the e-mail value already passed its own check).
  final String? passwordError;

  /// `AUTH_INVALID`/`Failure.message` from the backend call. Shown once,
  /// under the senha field, while *both* fields get the error border (the
  /// e-mail field via `errorText: ''`, border-only).
  final String? formError;

  final Resource<Unit> status;

  bool get isSubmitting => status is ResourceLoading<Unit>;

  AuthState copyWith({
    AuthMode? mode,
    String? email,
    String? password,
    String? emailError,
    bool clearEmailError = false,
    String? passwordError,
    bool clearPasswordError = false,
    String? formError,
    bool clearFormError = false,
    Resource<Unit>? status,
  }) {
    return AuthState(
      mode: mode ?? this.mode,
      email: email ?? this.email,
      password: password ?? this.password,
      emailError: clearEmailError ? null : (emailError ?? this.emailError),
      passwordError: clearPasswordError
          ? null
          : (passwordError ?? this.passwordError),
      formError: clearFormError ? null : (formError ?? this.formError),
      status: status ?? this.status,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is AuthState &&
          other.mode == mode &&
          other.email == email &&
          other.password == password &&
          other.emailError == emailError &&
          other.passwordError == passwordError &&
          other.formError == formError &&
          other.status == status);

  @override
  int get hashCode => Object.hash(
    mode,
    email,
    password,
    emailError,
    passwordError,
    formError,
    status,
  );

  @override
  String toString() =>
      'AuthState(mode: $mode, email: $email, password: $password, '
      'emailError: $emailError, passwordError: $passwordError, '
      'formError: $formError, status: $status)';
}

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../entities/session_status.dart';

/// The epic's ONE new DI-singleton access point for session validity (AD) —
/// every later consumer (Story 1.5's overlay, Story 1.6's `go_router`
/// redirect, Epic 4/RF07) listens to [statusStream] rather than re-deriving
/// session validity from a raw 401 or a second stream (RNF09 — still
/// `Either<Failure, T>` for the one-shot [restoreSession] call).
abstract class SessionRepository {
  /// Broadcast stream of the current session status. Emits nothing until
  /// [restoreSession] (or a later story's own trigger) completes at least
  /// once — a `StreamBuilder` with no data yet is the brief-blank boot state
  /// `main.dart` relies on (RNF01's 300ms threshold).
  Stream<SessionStatus> get statusStream;

  /// The last status emitted on [statusStream], read synchronously — `null`
  /// until [restoreSession] (or [markAuthenticated]) emits for the first
  /// time. Story 1.6's `go_router` `redirect` reads this directly (instead
  /// of awaiting the stream) so a redirect evaluation triggered the very
  /// same microtask as a status change always sees the up-to-date value.
  SessionStatus? get currentStatus;

  /// Boot-time, unconditional refresh: exchanges any stored refresh token
  /// for a fresh pair via `auth-refresh`, persists the result, and emits the
  /// outcome on [statusStream]. No client-side expiry math — the server is
  /// the sole source of truth for validity.
  Future<Either<Failure, Unit>> restoreSession();

  /// Story 1.6 — called by `AuthCubit.submit()`'s success branch, *before*
  /// it emits its own success state, so that a fresh login/signup is
  /// immediately reflected here: the access token is already persisted by
  /// that point (the repository saved it ahead of resolving), so this is a
  /// pure in-memory status flip, never a network/storage call. Without this
  /// running first, the `go_router` redirect triggered by the subsequent
  /// navigation would still see the pre-login status and bounce the user
  /// straight back to `/auth`.
  void markAuthenticated();

  /// Releases the underlying stream resource. Wired as `get_it`'s
  /// `dispose:` callback on registration, so `resetCoreDependencies()`
  /// (`sl.reset()`) closes it instead of leaking a `StreamController` on
  /// every test teardown.
  Future<void> dispose();
}

/// The epic's one session-status enum (AD — "exactly one `SessionStatus`
/// stream exposed from the auth feature's domain layer"). No `loading`/`idle`
/// member: a `StreamBuilder` with no data yet is this story's "loading"
/// representation (`main.dart`), never an extra enum value for that.
///
/// Story 1.5 adds [expired] — a mid-session `AUTH_EXPIRED` while
/// [authenticated], signalled via `SessionExpiryNotifier` and bridged onto
/// this same stream by `SessionRepositoryImpl`. `main.dart` renders the
/// same authenticated screen for both [authenticated] and [expired],
/// showing a recovery overlay only for the latter — never a third screen.
/// Per the spec's "Ask First" boundary, a future fourth value requires
/// renegotiating the epic's AD before being added.
enum SessionStatus { authenticated, unauthenticated, expired }

